      "policy_quote": "Dates can be changed with `change_dates` only if the new dates are available (`check_availability` returns `available: true` for the room type and the exact new dates) and the reservation is not `non_refundable`.",
      "requirement": "The new dates (2025-10-11 to 2025-10-14) must be confirmed available for the room type `deluxe_double` via `check_availability` before executing `change_dates`."
    },
    {
      "target_id": "t0",
      "policy_source_id": "q15",
      "policy_quote": "The new total equals nightly_rate × number of nights. Quote it before confirmation.",
      "requirement": "The new total price (nightly_rate × number of nights for the new dates) must be calculated and quoted to the guest before obtaining confirmation."
    },
    {
      "target_id": "t0",
      "policy_source_id": "q15",
      "policy_quote": "Before `change_dates`, list the details and obtain explicit confirmation (\"yes\"/\"да\").",
      "requirement": "Explicit confirmation from the guest must be obtained before executing `change_dates`."
    },
    {
      "target_id": "t0",
      "policy_source_id": "q15",
      "policy_quote": "Look up the guest with `get_guest` by guest ID and confirm the guest's last name before acting. Act only on reservations of that guest.",
      "requirement": "The guest must be confirmed as the owner of the reservation (last name verified) before proceeding with `change_dates`."
    },
    {
      "target_id": "t0",
      "policy_source_id": "q15",
      "policy_quote": "You cannot create new reservations or change rates.",
      "requirement": "The action must not alter the nightly rate or introduce any changes to the reservation beyond the specified date shift."
    }
  ]
}
